import{X as e,Y as t,ct as n,t as r}from"./chunks/framework.CaFWb3SA.js";var i=JSON.parse(`{"title":"Emuera 术语表","description":"","frontmatter":{},"headers":[],"relativePath":"translation/Glossary.md","filePath":"translation/Glossary.md"}`),a={name:`translation/Glossary.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="emuera-术语表" tabindex="-1">Emuera 术语表 <a class="header-anchor" href="#emuera-术语表" aria-label="Permalink to “Emuera 术语表”">​</a></h1><blockquote><p>翻译自原文档：<a href="https://osdn.net/projects/emuera/wiki/EmuDic" target="_blank" rel="noreferrer">https://osdn.net/projects/emuera/wiki/EmuDic</a></p></blockquote><p>这里汇总了本 wiki 中使用的术语。随着 Emuera 的扩展，原创词越来越多，因此作为备忘记录下来。</p><h2 id="启动模式" tabindex="-1">启动模式 <a class="header-anchor" href="#启动模式" aria-label="Permalink to “启动模式”">​</a></h2><h3 id="普通模式-normal-mode" tabindex="-1">普通模式 Normal Mode <a class="header-anchor" href="#普通模式-normal-mode" aria-label="Permalink to “普通模式 Normal Mode”">​</a></h3><p>Emuera 正常启动时的模式。</p><p>双击 <code>EmueraXXXX.exe</code> 启动时就会进入该模式。</p><h3 id="解析模式-analysis-mode" tabindex="-1">解析模式 Analysis Mode <a class="header-anchor" href="#解析模式-analysis-mode" aria-label="Permalink to “解析模式 Analysis Mode”">​</a></h3><p>以文件作为命令行参数调用时的模式。</p><p>把文件拖放到 <code>EmueraXXXX.exe</code> 上时也会进入该模式。解析模式会对拖放的文件进行语法检查，因此可以检查正在开发的文件是否存在语法错误。</p><p>不过，为了检查元素字符串的类型，需要准备你计划使用的改造版的 <code>CSV</code> 文件夹。</p><p>只要把文件拖放到你计划使用的改造版的 <code>EmueraXXXX.exe</code> 上即可。</p><p>另外，从 1738g 开始，在解析模式下启用<code>加载时显示报告</code>后，即可显示加载时的报告，并列出每个被加载的 <code>ERB</code> 文件中使用的函数。如果函数太多，请增大配置中日志的行数。</p><h3 id="调试模式-debug-mode" tabindex="-1">调试模式 Debug Mode <a class="header-anchor" href="#调试模式-debug-mode" aria-label="Permalink to “调试模式 Debug Mode”">​</a></h3><p>以 <code>-debug</code> 作为命令行参数启动时的模式。详情请参阅<a href="./Debug_Mode.html">调试模式</a>。</p><h2 id="窗口与对话框-windows-dialogs" tabindex="-1">窗口与对话框 Windows / Dialogs <a class="header-anchor" href="#窗口与对话框-windows-dialogs" aria-label="Permalink to “窗口与对话框 Windows / Dialogs”">​</a></h2><h3 id="主窗口-main-window" tabindex="-1">主窗口 Main Window <a class="header-anchor" href="#主窗口-main-window" aria-label="Permalink to “主窗口 Main Window”">​</a></h3><p>正常启动时最先打开的窗口。</p><h3 id="主控制台-main-console" tabindex="-1">主控制台 Main Console <a class="header-anchor" href="#主控制台-main-console" aria-label="Permalink to “主控制台 Main Console”">​</a></h3><p>主窗口中用于输入输出的部分的名称。</p><h3 id="调试窗口-debug-window" tabindex="-1">调试窗口 Debug Window <a class="header-anchor" href="#调试窗口-debug-window" aria-label="Permalink to “调试窗口 Debug Window”">​</a></h3><p>以调试模式启动时可以打开的窗口。</p><h3 id="调试控制台-debug-console" tabindex="-1">调试控制台 Debug Console <a class="header-anchor" href="#调试控制台-debug-console" aria-label="Permalink to “调试控制台 Debug Console”">​</a></h3><p>在调试窗口中选择<code>控制台</code>选项卡时显示出来的输入输出部分的名称。</p><h3 id="设置对话框-configuration-dialog" tabindex="-1">设置对话框 Configuration Dialog <a class="header-anchor" href="#设置对话框-configuration-dialog" aria-label="Permalink to “设置对话框 Configuration Dialog”">​</a></h3><p>可以从主窗口的<code>帮助</code>、<code>设置</code>菜单中打开的对话框。</p><h3 id="剪贴板对话框-clipboard-dialog" tabindex="-1">剪贴板对话框 Clipboard Dialog <a class="header-anchor" href="#剪贴板对话框-clipboard-dialog" aria-label="Permalink to “剪贴板对话框 Clipboard Dialog”">​</a></h3><p>在主控制台中按 <code>Ctrl+C</code> 可以打开的对话框。</p><h2 id="函数" tabindex="-1">函数 <a class="header-anchor" href="#函数" aria-label="Permalink to “函数”">​</a></h2><h3 id="命令-command" tabindex="-1">命令 Command <a class="header-anchor" href="#命令-command" aria-label="Permalink to “命令 Command”">​</a></h3><p>例如 <code>PRINT</code>、<code>WAIT</code> 等。</p><p>注意区分<strong>命令</strong>与<strong>函数</strong>。</p><h3 id="函数-function" tabindex="-1">函数 Function <a class="header-anchor" href="#函数-function" aria-label="Permalink to “函数 Function”">​</a></h3><p>在 <code>ERB</code> 脚本中用 <code>@~~</code> 语句定义名称，并通过 <code>CALL</code> 指令等调用的东西。</p><p>广义的函数也包括同样以 <code>@~~</code> 形式定义、但可以直接在表达式中使用的<a href="#表达式内函数">表达式内函数</a>。</p><h3 id="事件函数-event-function" tabindex="-1">事件函数 Event Function <a class="header-anchor" href="#事件函数-event-function" aria-label="Permalink to “事件函数 Event Function”">​</a></h3><p>名称以 <code>EVENT</code> 开头、由系统调用的函数。</p><p>如果定义了多个，它们都会被调用。</p><h3 id="预处理指令-preprocessor" tabindex="-1">预处理指令 Preprocessor <a class="header-anchor" href="#预处理指令-preprocessor" aria-label="Permalink to “预处理指令 Preprocessor”">​</a></h3><p><code>ERB</code> 文件夹中的文件中，先于其他任何指令被处理的行。</p><p>它以 <code>#</code> 开头，或由 <code>[]</code> 括起来的词句构成。</p><p>以 <code>#</code> 开头的行分为属性和定义，详情请参阅各自条目。</p><p>由 <code>[]</code> 括起来的词句表示特殊的区块，详情请参阅<a href="./Function_and_Preprocessor.html">函数与预处理器</a>。</p><h3 id="属性-预处理指令-attribute-preprocessor" tabindex="-1">属性（预处理指令）Attribute (Preprocessor) <a class="header-anchor" href="#属性-预处理指令-attribute-preprocessor" aria-label="Permalink to “属性（预处理指令）Attribute (Preprocessor)”">​</a></h3><p>为函数指定以 <code>#</code> 开头的行，用以决定该函数类型和行为的预处理指令。</p><p><code>#PRI</code>、<code>#LATER</code>、<code>#SINGLE</code>、<code>#ONLY</code> 用于控制事件函数执行时的行为。</p><p><code>#FUNCTION</code>、<code>#FUNCTIONS</code> 用于指定该函数在表达式中的类型。</p><h3 id="定义-预处理指令-definition-preprocessor" tabindex="-1">定义（预处理指令）Definition (Preprocessor) <a class="header-anchor" href="#定义-预处理指令-definition-preprocessor" aria-label="Permalink to “定义（预处理指令）Definition (Preprocessor)”">​</a></h3><p>以 <code>#</code> 开头的行中，用于定义变量名称及其类型的预处理指令。</p><p>其中有指定 <code>LOCAL</code>、<code>LOCALS</code> 变量元素数的 <code>#LOCALSIZE</code>、<code>#LOCALSSIZE</code>，定义变量的 <code>#DIM</code>、<code>#DIMS</code>，以及在 <code>ERH</code> 中定义宏的 <code>#DEFINE</code>。</p><h3 id="可在表达式中使用的函数" tabindex="-1">可在表达式中使用的函数 <a class="header-anchor" href="#可在表达式中使用的函数" aria-label="Permalink to “可在表达式中使用的函数”">​</a></h3><p>可以从表达式中调用的<strong>函数</strong>。</p><p>这里的<strong>函数</strong>不仅包括上面所述的函数，也包括下面说明的内置函数。</p><p>在许多编程语言中，它们被直接称为“函数”。</p><h3 id="表达式内函数" tabindex="-1">表达式内函数 <a class="header-anchor" href="#表达式内函数" aria-label="Permalink to “表达式内函数”">​</a></h3><p>可在表达式中使用的函数的简称。</p><p>它与编程语言中的匿名函数或内联函数没有关系。</p><p>注意区分<strong>指令</strong>、<strong>函数</strong>、<strong>表达式内函数</strong>的不同使用方式。</p><h3 id="内置函数-built-in-function" tabindex="-1">内置函数 Built-in Function <a class="header-anchor" href="#内置函数-built-in-function" aria-label="Permalink to “内置函数 Built-in Function”">​</a></h3><p>表达式内函数中，一开始就内置在 Emuera 里、无需通过 <code>@~~</code> 语句定义即可使用的东西。</p><p>例如 <code>ABS(X)</code>、<code>GETTIME()</code> 等。</p><p>虽然容易混淆，但它们并不符合上面所述函数的定义。把它们理解为“可用于表达式中的指令”或许更好懂。</p><h3 id="用户定义函数-user-defined-function" tabindex="-1">用户定义函数 User-defined Function <a class="header-anchor" href="#用户定义函数-user-defined-function" aria-label="Permalink to “用户定义函数 User-defined Function”">​</a></h3><p>用户定义的函数。</p><p>即在 <code>ERB</code> 脚本中用 <code>@~~</code> 语句定义名称，并通过 <code>CALL</code> 指令等调用的东西。</p><p>也就是说，与上面所述的函数是同一个概念。</p><h3 id="function-s-函数" tabindex="-1">#FUNCTION(S) 函数 <a class="header-anchor" href="#function-s-函数" aria-label="Permalink to “#FUNCTION(S) 函数”">​</a></h3><p>用 <code>@~~</code> 语句定义名称、并带有 <code>#FUNCTION(S)</code> 属性的函数。</p><p>它既是函数，又是表达式内函数。</p><h2 id="行、语句、表达式" tabindex="-1">行、语句、表达式 <a class="header-anchor" href="#行、语句、表达式" aria-label="Permalink to “行、语句、表达式”">​</a></h2><h3 id="行" tabindex="-1">行 <a class="header-anchor" href="#行" aria-label="Permalink to “行”">​</a></h3><p>从一个换行符到下一个换行符之间的内容。</p><p>在编程相关的语境中也被称为物理行。</p><p>容易混淆的是，在编辑器相关的语境中，它常被称为逻辑行。</p><h3 id="语句" tabindex="-1">语句 <a class="header-anchor" href="#语句" aria-label="Permalink to “语句”">​</a></h3><p>语句或逻辑行是 Emuera 中的一个处理单位。</p><p>大多数语句由一条指令及其参数，或者由变量、赋值运算符和表达式构成。</p><p>由于 <code>ERB</code> 中有一行一句的铁则，行与语句的含义几乎相同，本 wiki 也不对二者加以区分。</p><h3 id="表达式" tabindex="-1">表达式 <a class="header-anchor" href="#表达式" aria-label="Permalink to “表达式”">​</a></h3><p>由变量、常数、表达式内函数、非赋值运算符、括号及其组合构成的内容。</p><p>赋值运算符只能作为赋值语句中的第一个运算符使用，不能在表达式中使用。</p><h3 id="数值表达式" tabindex="-1">数值表达式 <a class="header-anchor" href="#数值表达式" aria-label="Permalink to “数值表达式”">​</a></h3><p>求值结果（运算结果）为数值的表达式。</p><p>例如 <code>A + B</code>、<code>STR == &quot;Ayu&quot;</code> 等。</p><h3 id="字符串表达式" tabindex="-1">字符串表达式 <a class="header-anchor" href="#字符串表达式" aria-label="Permalink to “字符串表达式”">​</a></h3><p>求值结果（运算结果）为字符串的表达式。</p><p>例如 <code>STR + STR:1</code>、<code>&quot;a&quot; * 10</code> 等。</p><h2 id="变量" tabindex="-1">变量 <a class="header-anchor" href="#变量" aria-label="Permalink to “变量”">​</a></h2><h3 id="伪变量" tabindex="-1">伪变量 <a class="header-anchor" href="#伪变量" aria-label="Permalink to “伪变量”">​</a></h3><p>像 <code>RAND</code>、<code>CHARANUM</code> 这样可以按变量的形式书写，但实际上并不是变量的东西。</p><p>其内部行为接近于表达式内函数。</p><h3 id="数组变量" tabindex="-1">数组变量 <a class="header-anchor" href="#数组变量" aria-label="Permalink to “数组变量”">​</a></h3><p>拥有多个元素的变量。</p><p>数组变量的元素数可以在 <code>VariableSize.csv</code> 中修改，通常不会在脚本中增减，但一部分局部变量可以在脚本中指定数组的元素数。</p><h3 id="角色变量-character-variable" tabindex="-1">角色变量 Character Variable <a class="header-anchor" href="#角色变量-character-variable" aria-label="Permalink to “角色变量 Character Variable”">​</a></h3><p>记录角色状态的变量。</p><p>它与 C 语言等中的 char 型变量没有关系。</p><p>由于其性质，元素数会随着 <code>ADDCHARA</code>、<code>DELCHARA</code> 导致的角色增减而增减。</p><p><code>NO:TARGET</code> 等以与数组变量相同的形式指定元素，因此在 Eramaker 的说明中它被当作数组变量之一，但本 wiki 将角色变量与数组变量区分开来。</p><h3 id="双重数组变量" tabindex="-1">双重数组变量 <a class="header-anchor" href="#双重数组变量" aria-label="Permalink to “双重数组变量”">​</a></h3><p>既是角色变量、又是数组变量的变量。</p><p>如 <code>CFLAG:TARGET:2</code> 这样接受两个参数（可省略）。</p><p>由于它是角色变量，第一个参数表示角色编号；并且随着角色的增减，第一维的元素数也会增减。</p><p>第二维的元素数只能在 <code>VariableSize.csv</code> 中修改，不能在脚本中增减。</p><p>本 wiki 除了说明 Eramaker 的规范之外，不使用“双重数组”这一术语，而使用“既是角色变量又是数组变量”之类的说法。</p><h3 id="多维数组变量" tabindex="-1">多维数组变量 <a class="header-anchor" href="#多维数组变量" aria-label="Permalink to “多维数组变量”">​</a></h3><p>如 <code>DITEMTYPE</code> 这样的二维数组变量，以及如 <code>TA</code> 这样的三维数组变量。</p><p>它们像 <code>DA:0:1</code> 或 <code>TA:1:2:3</code> 这样接受两个或三个参数。</p><p>多维数组变量的元素数只能在 <code>VariableSize.csv</code> 中修改，不能在脚本中增减，而且其参数不能省略。</p><h3 id="角色多维数组变量" tabindex="-1">角色多维数组变量 <a class="header-anchor" href="#角色多维数组变量" aria-label="Permalink to “角色多维数组变量”">​</a></h3><p>既是角色变量、又是多维数组变量的变量。</p><p>如 <code>CFLAG:TARGET:0:2</code> 这样接受三个参数（不可省略）。</p><p>由于它是角色变量，第一个参数表示角色编号；并且随着角色的增减，第一维的元素数也会增减。</p><p>第二维、第三维的元素数只能在 <code>VariableSize.csv</code> 中修改，不能在脚本中增减。</p><p>截至 ver1807，符合这一变量的只有 <code>CDFLAG</code>。详情请参阅 <code>CDFLAG</code>。</p><h3 id="局部变量-local-variable" tabindex="-1">局部变量 Local Variable <a class="header-anchor" href="#局部变量-local-variable" aria-label="Permalink to “局部变量 Local Variable”">​</a></h3><p><code>LOCAL</code>、<code>LOCALS</code> 以及私有变量等按函数（函数名）分别准备的变量。</p><p>私有变量请参阅另一条目。</p><p>除私有变量以外的 <code>LOCAL</code> 和 <code>LOCALS</code>，实际上并不是所谓的局部变量，而是名为 <code>LOCAL@函数名</code>、<code>LOCALS@函数名</code> 的 public static 变量。</p><p>即使离开了函数，值也会被保留，并且可以从函数外部赋值、引用。</p><p>在递归调用等多次调用的情况下，值也会被共享。</p><h3 id="广域变量-nonlocal-variable" tabindex="-1">广域变量 Nonlocal Variable <a class="header-anchor" href="#广域变量-nonlocal-variable" aria-label="Permalink to “广域变量 Nonlocal Variable”">​</a></h3><p>除 <code>LOCAL</code>、<code>LOCALS</code> 和私有变量等之外，几乎所有变量都属于这一类，是在所有函数间共享值的变量。</p><p>可以说它相当于一般编程语言中的全局变量概念。</p><p>此外，在 <code>ERH</code> 中使用 <code>#DIM</code> 或 <code>#DIMS</code> 也可以定义广域变量。</p><p>详情请参阅<a href="./Header_File.html">头文件（ERH）</a>。</p><h3 id="全局变量-global-variable" tabindex="-1">全局变量 Global Variable <a class="header-anchor" href="#全局变量-global-variable" aria-label="Permalink to “全局变量 Global Variable”">​</a></h3><p>可以在不同存档之间共享值的变量。全局变量也包含在广域变量之中。</p><p>它与普通变量在保存、读取和初始化的时机上不同。</p><p>Emuera 中的全局变量与一般编程语言中的全局变量概念没有关系。</p><h3 id="私有变量-private-variable" tabindex="-1">私有变量 Private Variable <a class="header-anchor" href="#私有变量-private-variable" aria-label="Permalink to “私有变量 Private Variable”">​</a></h3><p>按函数（函数名）通过 <code>#DIM</code> 或 <code>#DIMS</code> 定义的变量。</p><p>它们也是局部变量，因此对每个函数都是独立的。</p><p>不过，与同样被视为局部变量的 <code>LOCAL</code> 等不同，不能用 <code>@函数名</code> 之类的方式从函数外部赋值或引用。</p><p>详情请参阅<a href="./Custom_Variable.html">用户自定义变量</a>。</p>`,135)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};